"use strict";const t=require("./request.js"),r=require("./urls.js"),e=require("./adapters.js");exports.createProduct=function(u){return t.post(r.API.products,e.toProductPayload(u))},exports.getMyProducts=function(u){return t.get(r.API.productsMine,u).then(t=>e.mapPage(t,e.mapProduct))},exports.getProductDetail=function(u){return t.get(r.API.productDetail(u)).then(e.mapProduct)},exports.getProducts=function(u){return t.get(r.API.products,u).then(t=>e.mapPage(t,e.mapProduct))},exports.updateProductStatus=function(e,u){return t.put(r.API.productStatus(e),{status:"off"===u?0:1})};
